<?php require '../common.php';startpage('Hotel Admin');nav('<a href="index.php">Rooms</a><a href="history.php">Bookings</a>');$msg='';if($_SERVER['REQUEST_METHOD']==='POST'){$id=(int)$_POST['id'];$p=(float)$_POST['price'];$q=(int)$_POST['quantity'];$s=$conn->prepare('UPDATE rooms SET price=?,quantity=? WHERE id=?');$s->bind_param('dii',$p,$q,$id);$s->execute();$msg='Room updated.';}if($msg)echo '<p class="msg">'.e($msg).'</p>';$rs=$conn->query('SELECT * FROM rooms');?><table><tr><th>Room</th><th>Price</th><th>Quantity</th><th>Update</th></tr><?php while($r=$rs->fetch_assoc()):?><tr><form method="post"><td><?=e($r['room_type'])?><input type="hidden" name="id" value="<?=$r['id']?>"></td><td><input type="number" step=".01" name="price" value="<?=$r['price']?>"></td><td><input type="number" name="quantity" value="<?=$r['quantity']?>"></td><td><button>Save</button></td></form></tr><?php endwhile;?></table><p>Room prices and quantities can be changed here. Add static pages for About, Contact, FAQ, travel guide and privacy policy as required.</p><?php endpage();?>